    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val == 5:
                r1 = min(r1, r)
                r2 = max(r2, r)
                c1 = min(c1, c)
                c2 = max(c2, c)

    output = [[0]*w for _ in range(h)]

    # Center 0s: 3x3 from r1+3 to r2-3, c1+3 to c2-3
    center_r_start = r1 + 3
    center_r_end = r2 - 3
    center_c_start = c1 + 3
    center_c_end = c2 - 3

    inner5_r_adj, inner5_r_down, inner5_c_adj, inner5_c_down = r1 + 2, r2 - 2, c1 + 2, c2 - 2
    inner2_r_adj, inner2_r_down, inner2_c_adj, inner2_c_down = r1 + 1, r2 - 1, c1 + 1, c2 - 1

    for r in range(r1, r2 + 1):
